import { isUndefined } from 'lodash-es';
import React, { PropsWithChildren } from 'react';

import { container } from './PieChartOverlays.sty.js';
import { useToolbarConfig } from '../../context/ToolbarContext.js';
import { useTooltipVisibility } from '../../hooks/store/selectors.js';
import { useOverlayHandlers } from '../../hooks/useOverlayHandlers.js';
import { InternalSliceData } from '../../types/internal/pie-chart.js';
import { PieChartToolbar } from '../toolbar/PieChartToolbar.js';
import { PieChartTooltip } from '../tooltip/PieChartTooltip.js';

interface PieChartOverlaysProps {
  slices: InternalSliceData[];
}

export const PieChartOverlays = ({
  children,
  slices,
}: PropsWithChildren<PieChartOverlaysProps>) => {
  const { onMouseEnterHandler, onMouseLeaveHandler } = useOverlayHandlers();

  const toolbarConfig = useToolbarConfig();
  const shouldShowToolbar = !isUndefined(toolbarConfig);

  const isTooltipVisible = useTooltipVisibility();

  return (
    <div
      data-testid="overlays-wrapper"
      className={container}
      onMouseEnter={onMouseEnterHandler}
      onMouseLeave={onMouseLeaveHandler}
    >
      {isTooltipVisible && <PieChartTooltip />}
      {shouldShowToolbar && <PieChartToolbar />}
      {children}
    </div>
  );
};
